<?= $this->extend('layouts/tenant_admin') ?><?= $this->section('content') ?><?php $tenantContext=service('tenantContextManager')->current();$can=static fn(string $authority):bool=>service('tenantAccess')->hasAuthority($tenantContext,$authority);?>
<header class="page-head"><p class="eyebrow">Website &amp; CMS</p><h1>Website dashboard</h1><p><span class="badge badge-<?= $enabled?'active':'suspended' ?>"><?= $enabled?'Public website enabled':'Public website disabled' ?></span> <a href="<?= esc($publicUrl) ?>">View public website</a></p></header>
<section class="metric-grid"><article class="metric"><strong><?= esc($completion) ?>%</strong><span>Setup complete</span></article><?php foreach($contentCounts as $status=>$count):?><article class="metric"><strong><?= esc($count) ?></strong><span><?= esc(ucwords(str_replace('_',' ',$status))) ?></span></article><?php endforeach?></section>
<section class="action-grid" aria-label="Website workspaces"><?php foreach([['website.settings.manage','tenant/website/settings','Website settings','Identity, contact, homepage, and launch settings.'],['website.menu.manage','tenant/website/menu','Navigation menu','Manage and order public navigation.'],['website.content.view','tenant/website/editorial/news','News','Create and publish school news.'],['website.content.view','tenant/website/editorial/announcements','Announcements','Maintain public announcements.'],['website.content.view','tenant/website/editorial/calendar','Calendar','Maintain public calendar entries.'],['website.media.manage','tenant/website/media','Media library','Upload and manage website media.'],['website.content.edit','tenant/website/showcase/departments','Academic showcase','Maintain department and programme profiles.'],['website.content.edit','tenant/website/institutional/management','Management showcase','Maintain public leadership information.'],['website.media.manage','tenant/website/institutional/gallery','Gallery','Maintain public gallery albums.'],['website.audit.view','tenant/website/audit','Website audit','Review editorial activity.']] as [$authority,$route,$label,$description]):?><?php if($can($authority)):?><a class="action-card" href="<?= site_url($route) ?>"><strong><?= esc($label) ?></strong><span class="muted"><?= esc($description) ?></span></a><?php endif?><?php endforeach?></section>
<section class="panel"><h2>Setup checklist</h2><div class="admin-grid" aria-label="Website setup checklist"><?php foreach($checklist as $label=>$complete): ?><article class="admin-card"><span class="badge badge-<?= $complete?'active':'pending' ?>"><?= $complete?'Complete':'Needs attention' ?></span><h3><?= esc(ucwords(str_replace('_',' ',$label))) ?></h3></article><?php endforeach ?></div></section>
<div class="split-grid"><section class="panel"><h2>Institutional showcase</h2><ul class="record-list"><li>Published departments <strong><?= esc($profileCounts['departments']) ?></strong></li><li>Published programmes <strong><?= esc($profileCounts['programmes']) ?></strong></li><li>Public gallery albums <strong><?= esc($galleryCounts['albums']) ?></strong></li><li>Public gallery images <strong><?= esc($galleryCounts['images']) ?></strong></li></ul></section><section class="panel"><h2>Scheduled publication queue</h2><?php if($scheduledQueue===[]):?><div class="empty">No content is scheduled.</div><?php else:?><ul class="record-list"><?php foreach($scheduledQueue as $item): ?><li><strong><?= esc($item['title']) ?></strong><br><small><?= esc($item['scheduled_for']) ?></small></li><?php endforeach ?></ul><?php endif?></section></div><section class="panel"><h2>Recent website audit events</h2><?php if($recentAudit===[]):?><div class="empty">No recent website activity.</div><?php else:?><ul class="record-list"><?php foreach($recentAudit as $event): ?><li><strong><?= esc(str_replace('_',' ',$event['action'])) ?></strong> <small><?= esc($event['created_at']) ?></small></li><?php endforeach ?></ul><?php endif?></section>
<?= $this->endSection() ?>
